-- Luồng khung tới thanh toán kỳ và hoàn cọc, không owner cho bước nghiệp vụ.
SELECT set_config('test.fw.data',(SELECT jsonb_build_object('code','C47-FW-FULL','seller_org_id',f.seller_org_id,'segment_code',f.segment_code,'schedule',f.schedule,'price_period',f.price_period,'billing_period',f.billing_period,'framework_deposit_vnd',f.framework_deposit_vnd,'active_during',f.active_during)::text FROM core.framework_contracts f WHERE code='C43-FRAMEWORK'),true),set_config('test.fw.doc',test.command_doc('C47-FW-FULL-DOC')::text,true),set_config('test.fw.bank',(SELECT id::text FROM pii.bank_accounts WHERE org_id=test.org('TC-B01') AND status='active'),true);
SELECT set_config('test.fw.lines',jsonb_build_array(jsonb_build_object('lot_id',test.id('C43LOT:lot'),'qty',10000))::text,true);
SELECT test.as_login('db_test_buyer',$$SELECT set_config('test.fw.id',cmd.create_framework(current_setting('test.fw.data')::jsonb,current_setting('test.fw.doc')::jsonb,current_setting('test.fw.bank')::uuid)::text,true)$$);
SELECT set_config('test.fw.docid',(SELECT document_id::text FROM core.framework_terms WHERE framework_id=current_setting('test.fw.id')::uuid),true);
SELECT set_config('test.fw.otp',test.otp(current_setting('test.fw.docid')::uuid,test.person('Trần Thu Hà')),true);
SELECT test.as_login('db_test_buyer',$$SELECT cmd.sign_document(current_setting('test.fw.docid')::uuid,'buyer',current_setting('test.fw.otp'),'TEST')$$);
SELECT test.as_login('db_test_buyer',$$SELECT cmd.send_framework(current_setting('test.fw.id')::uuid)$$);
SELECT set_config('test.fw.otp',test.otp(current_setting('test.fw.docid')::uuid,test.person('Nguyễn Thị Năm')),true);
SELECT test.as_login('db_test_seller',$$SELECT cmd.sign_document(current_setting('test.fw.docid')::uuid,'seller',current_setting('test.fw.otp'),'TEST')$$);
SELECT test.as_login('db_test_seller',$$SELECT cmd.finalize_framework(current_setting('test.fw.id')::uuid,'C47-FW-REF','C47-FW-VA','bank_sim')$$);
SELECT test.apply_bank_event(test.bank_receipt('C47-FW-FUND',1000000,'C47-FW-REF'));
SELECT test.as_login('db_test_system',$$SELECT cmd.activate_framework(current_setting('test.fw.id')::uuid)$$);
SELECT set_config('test.fw.terms',jsonb_build_object('delivery_window',tstzrange(now()+interval '2 days',now()+interval '3 days'),'delivery_mode','at_buyer_warehouse','acceptance_point','tai_kho_ben_mua','transport_by','seller','designated_receiver_user_id',test.person('Võ Hoàng Phúc'))::text,true);
SELECT test.as_login('db_test_buyer',$$SELECT set_config('test.fw.order',cmd.create_calloff(current_setting('test.fw.id')::uuid,'C47-FW-CALL',current_setting('test.fw.terms')::jsonb,current_setting('test.fw.lines')::jsonb)::text,true)$$);
SELECT test.as_login('db_test_system',$$SELECT set_config('test.c47.delivery',cmd.activate_calloff(current_setting('test.fw.order')::uuid)::text,true)$$);
SELECT set_config('test.c47.receiver',test.person('Võ Hoàng Phúc')::text,true);
SELECT test.as_login('db_test_buyer',$$SELECT set_config('test.c47.qr',cmd.assign_receiver(current_setting('test.c47.delivery')::uuid,current_setting('test.c47.receiver')::uuid),true)$$);
INSERT INTO cmd.test_clock(at) VALUES(now()+interval '2 days 1 hour');
SELECT test.as_login('db_test_system',$$SELECT cmd.ready_delivery(current_setting('test.c47.delivery')::uuid)$$);
SELECT test.as_login('db_test_seller',$$SELECT cmd.dispatch_delivery(current_setting('test.c47.delivery')::uuid)$$);
SELECT test.as_login('db_test_receiver',$$SELECT cmd.scan_qr(current_setting('test.c47.qr'),'TEST')$$);
SELECT test.as_login('db_test_receiver',$$SELECT cmd.start_acceptance(current_setting('test.c47.delivery')::uuid)$$);
SELECT set_config('test.c47.doc',test.command_doc('C47-FW-BBNT')::text,true),set_config('test.c47.lines',jsonb_build_array(jsonb_build_object('lot_id',(current_setting('test.fw.lines')::jsonb->0->>'lot_id')::uuid,'order_line_no',1,'kind','accepted','qty',10000,'payable_qty',10000,'unit_price_vnd',23000,'value_vnd',230000))::text,true);
SELECT test.as_login('db_test_receiver',$$SELECT set_config('test.c47.acceptance',cmd.submit_acceptance(current_setting('test.c47.delivery')::uuid,10000,current_setting('test.c47.doc')::jsonb,current_setting('test.c47.lines')::jsonb)::text,true)$$);
SELECT set_config('test.c47.docid',(SELECT document_id::text FROM core.acceptance_versions WHERE id=current_setting('test.c47.acceptance')::uuid),true);
SELECT test.sign_command_record('db_test_receiver',test.person('Võ Hoàng Phúc'),'buyer');
SELECT test.as_login('db_test_receiver',$$SELECT cmd.send_acceptance(current_setting('test.c47.acceptance')::uuid)$$);
SELECT test.sign_command_record('db_test_seller',test.person('Nguyễn Thị Năm'),'seller');
SELECT test.as_login('db_test_seller',$$SELECT cmd.agree_acceptance(current_setting('test.c47.acceptance')::uuid)$$);
SELECT test.as_login('db_test_seller',$$SELECT cmd.finish_warehouse_delivery(current_setting('test.c47.delivery')::uuid)$$);
SELECT test.as_login('db_test_system',$$SELECT cmd.create_settlement(current_setting('test.fw.order')::uuid,true,'C47-FW-FINAL')$$);
SELECT test.check('C47 gọi hàng quyết toán 230000 không tạo nghĩa vụ riêng',EXISTS(SELECT 1 FROM core.settlements WHERE order_id=current_setting('test.fw.order')::uuid AND is_final AND n_vnd=230000) AND NOT EXISTS(SELECT 1 FROM core.direct_payments WHERE order_id=current_setting('test.fw.order')::uuid));
SELECT set_config('test.fw.period',tstzrange(now()-interval '1 hour',now()+interval '1 hour')::text,true);
SELECT test.as_login('db_test_system',$$SELECT set_config('test.fw.periodid',cmd.bill_framework_period(current_setting('test.fw.id')::uuid,current_setting('test.fw.period')::tstzrange)::text,true)$$);
SELECT test.as_login('db_test_system',$$SELECT cmd.bill_framework_period(current_setting('test.fw.id')::uuid,current_setting('test.fw.period')::tstzrange)$$);
SELECT set_config('test.fw.payment',(SELECT payment_id::text FROM core.framework_periods WHERE id=current_setting('test.fw.periodid')::uuid),true),set_config('test.fw.evidence',test.command_doc('C47-FW-PAYMENT-PROOF')::text,true);
SELECT test.as_login('db_test_payer',$$SELECT set_config('test.fw.proof',cmd.attach_framework_evidence(current_setting('test.fw.id')::uuid,current_setting('test.fw.evidence')::jsonb)::text,true)$$);
SELECT test.as_login('db_test_payer',$$SELECT cmd.report_payment(current_setting('test.fw.payment')::uuid,230000,'bank_transfer',current_setting('test.fw.proof')::uuid)$$);
SELECT set_config('test.fw.otp',test.payment_otp(current_setting('test.fw.payment')::uuid,230000,test.person('Nguyễn Thị Năm')),true);
SELECT test.as_login('db_test_seller',$$SELECT cmd.confirm_direct_payment(current_setting('test.fw.payment')::uuid,230000,'full','C47-FW-PAID',current_setting('test.fw.otp'))$$);
SELECT test.check('C47 kỳ khung chỉ một hóa đơn, nhận tiền xóa công nợ khung',(SELECT count(*)=1 FROM core.framework_periods WHERE framework_id=current_setting('test.fw.id')::uuid) AND NOT EXISTS(SELECT 1 FROM ledger.v_account_balances WHERE framework_id=current_setting('test.fw.id')::uuid AND account_type IN ('seller_receivable','buyer_payable') AND balance_vnd<>0));
SELECT test.as_login('db_test_system',$$SELECT cmd.finish_order(current_setting('test.fw.order')::uuid)$$);
SELECT test.as_login('db_test_system',$$SELECT set_config('test.fw.closing',cmd.close_framework(current_setting('test.fw.id')::uuid),true)$$);
SELECT test.check('C47 đóng khung phát hoàn cọc và chờ đối soát',current_setting('test.fw.closing')='processing_money' AND EXISTS(SELECT 1 FROM core.bank_instructions WHERE basis_kind='framework_close' AND basis_id=current_setting('test.fw.id')::uuid AND amount_vnd=1000000 AND source_bank_event_id=test.id('C47-FW-FUND')));
SELECT set_config('test.fw.instruction',(SELECT id::text FROM core.bank_instructions WHERE basis_kind='framework_close' AND basis_id=current_setting('test.fw.id')::uuid),true);
SELECT test.as_login('db_test_system',$$SELECT cmd.send_instruction(current_setting('test.fw.instruction')::uuid)$$);
SELECT test.instruction_event('C47-FW-REFUND-OK',(SELECT code FROM core.bank_instructions WHERE id=current_setting('test.fw.instruction')::uuid),'instruction_succeeded',1000000);
SELECT set_config('test.fw.statement',test.command_statement('C47-FW-REFUND-STATEMENT',current_setting('test.fw.instruction')::uuid)::text,true);
SELECT test.as_login('db_test_system',$$SELECT cmd.reconcile_instruction(current_setting('test.fw.instruction')::uuid,current_setting('test.fw.statement')::uuid)$$);
SELECT test.as_login('db_test_system',$$SELECT cmd.close_framework(current_setting('test.fw.id')::uuid)$$);
SELECT test.check('C47 khung ended chỉ sau hoàn nguồn đối soát, sổ cọc bằng 0',EXISTS(SELECT 1 FROM core.framework_contracts WHERE id=current_setting('test.fw.id')::uuid AND status='ended') AND NOT EXISTS(SELECT 1 FROM ledger.v_account_balances WHERE framework_id=current_setting('test.fw.id')::uuid AND account_type IN ('deposit_escrow','deposit_in_instruction','seller_receivable','buyer_payable') AND balance_vnd<>0));
DELETE FROM cmd.test_clock;
SET CONSTRAINTS ALL IMMEDIATE;
